'use strict';
// ---------- царские приказы: задачи управленца — продуктовые, маркетинговые и денежные метрики ----------
// Пять приказов, в каждом три ступени: 1 — расчёт по формуле, 2 — обратная (неизвестное внутри формулы, решается уравнением),
// 3 — многошаговая. Генератор возвращает {q: условие, a: ответ, unit, u: как проверять ('num'|'pct'|'x'), r: знаков после запятой, s: шаги}.
// Как царь даёт поручения, чины и жалованье — ниже; правила и расчёт золота — docs/PROJECT.md, раздел 5 «Царские приказы».

// ---------- числа и слова ----------
const pzDec=a=>{for(let k=0;k<7;k++){const v=a*10**k;if(Math.abs(v-Math.round(v))<1e-6)return k}return 7};
// 12 000 · 7,5 · −3 (пробел в тысячах — с пяти знаков)
function nf(n,d=2){const neg=n<-1e-9;let[i,fr]=String(Math.round(Math.abs(n)*10**d)/10**d).split('.');if(i.length>4)i=i.replace(/\B(?=(\d{3})+(?!\d))/g,' ');return(neg?'−':'')+i+(fr?','+fr:'')}
const np=(n,d)=>nf(n,d)+'%',nr=n=>nf(n)+' руб.',nl=a=>a.map(x=>nf(x)).join(', ');
const pzPl=(n,a,b,c)=>{if(!Number.isInteger(n))return b;n=Math.abs(n);const m=n%10,h=n%100;return m===1&&h!==11?a:m>=2&&m<=4&&(h<12||h>14)?b:c};
const pzCap=s=>s[0].toUpperCase()+s.slice(1);
const pzEq=x=>pzDec(x)>2?'≈ '+nf(x,1):'= '+nf(x);  // «= 26,25» или «≈ 33,3» — как в ответе
const pzSup=n=>n===2?'²':n===3?'³':'^'+n;
const PZU={pct:['в процентах','%'],rub:['в рублях',' руб.'],pp:['в процентных пунктах',' п. п.'],x:['число: во сколько раз',''],mon:['число месяцев',' мес.']};
const U_DV=['число дворов','двор','двора','дворов'],U_KUP=['число купцов','купец','купца','купцов'],U_POK=['число покупателей','покупатель','покупателя','покупателей'],
  U_ZAK=['число заказов','заказ','заказа','заказов'],U_BUY=['число покупок','покупка','покупки','покупок'],U_GOST=['число гостей','гость','гостя','гостей'],U_SHOW=['число показов','показ','показа','показов'];
// задача: если точный ответ длиннее r знаков, в условии просим округлить, и допуск — половина последнего знака; точный ответ — без допуска (o.tol — свой допуск)
function pzQ(q,a,unit,s,o={}){a=+a.toFixed(6);const d=pzDec(a),r=o.r!==undefined?o.r:d>2?1:d,ph=Array.isArray(unit)?unit[0]:PZU[unit][0];
  return{q:`${q} Ответ — ${ph}${d>r?', округли до '+['целого','десятых','сотых'][r]:''}.`,a,unit,u:unit==='pct'?'pct':unit==='x'?'x':'num',r,round:d>r,tol:o.tol||0,abs:o.abs||0,s}}
function pzFa(p){const v=nf(p.a,p.r);return Array.isArray(p.unit)?v+' '+pzPl(p.a,p.unit[1],p.unit[2],p.unit[3]):v+PZU[p.unit][1]}

// ---------- сказочные вводные ----------
const PZ_SLOB=['Кузнецкой','Гончарной','Рыбной','Стрелецкой','Ямской','Кожевенной','Огородной','Плотницкой'];
const PZ_SVC=[['водовоз','водовозу','водовоза'],['трубочист','трубочисту','трубочиста'],['хлебник','хлебнику','хлебника'],['банщик','банщику','банщика']]; // кто, кому, кого
const PZ_GOODS=[{n:'кафтан',a:'кафтан',m:'портной',pr:'его'},{n:'пара сапог',a:'пару сапог',m:'сапожник',pr:'её'},{n:'шапка',a:'шапку',m:'шапочник',pr:'её'},
  {n:'седло',a:'седло',m:'шорник',pr:'его'},{n:'самовар',a:'самовар',m:'медник',pr:'его'}];
// точка безубыточности: v — сырьё на штуку, d — сколько остаётся со штуки
const PZ_BE=[{who:'Пекарня',it:'Пирог',on:'на него',one:'один пирог',mat:'мука и начинка',f:['пирог','пирога','пирогов'],ph:'число пирогов',v:[3,4,5,6],d:[5,6,8,10]},
  {who:'Кузница',it:'Подкова',on:'на неё',one:'одну подкову',mat:'железо и уголь',f:['подкова','подковы','подков'],ph:'число подков',v:[20,25,30],d:[10,15,20,25]},
  {who:'Свечная лавка',it:'Свеча',on:'на неё',one:'одну свечу',mat:'воск и фитиль',f:['свеча','свечи','свечей'],ph:'число свечей',v:[2,3,4],d:[2,3,4,5]},
  {who:'Корчма',it:'Миска щей',on:'на неё',one:'одну миску',mat:'капуста и мясо',f:['миска','миски','мисок'],ph:'число мисок щей',v:[6,8,10],d:[5,8,10,12]}];
const pzPick2=a=>{const x=pick(a);let y;do y=pick(a);while(y===x);return[x,y]};
const pzSum=a=>a.reduce((x,y)=>x+y,0);
const pzShuf=a=>{for(let i=a.length-1;i>0;i--){const j=R(0,i);[a[i],a[j]]=[a[j],a[i]]}return a};

// ---------- пять приказов ----------
const PZ_STEP=['прямой расчёт','обратная задача','многошаговая'];
const PZ_HOW=['Подставь числа в формулу.','Неизвестное обозначь буквой x, подставь в формулу и реши уравнение.','Сначала найди промежуточные величины, потом ответ.'];
const PZ=[
{id:'stat',name:'Приказ счётных дел',topic:'аналитика и статистика',what:'среднее, медиана, доли, прирост, A/B-тест',
 dyak:'Я дьяк Приказа счётных дел: / считаю всё, что царь велел.',
 tsar:'Мой Приказ счётных дел — / кто куда, и счёт не цел!',
 rules:['<b>Среднее</b> = сумма значений / их количество.','<b>Медиана</b> — число посередине упорядоченного ряда. Если чисел чётное количество — среднее двух средних. Одна богатая лавка тянет среднее вверх, а медиану — нет.',
  '<b>Доля</b> = часть / целое × 100%.','<b>Прирост</b> = (новое − старое) / старое × 100%. Минус — значит, упало. Два прироста подряд не складывают, а перемножают множители: +20% и +25% → 1,2 × 1,25 = 1,5, то есть +50%.',
  '<b>Процентный пункт</b> (п. п.) — разница двух процентов: было 5%, стало 7% — это +2 п. п., а в процентах — +40%.',
  '<b>A/B-тест</b>: поток делят на две части, каждой показывают свой вариант и сравнивают конверсии. Конверсия = сделали / все × 100%.'],
 ex:{q:'В прошлом году на ярмарку приехало 400 купцов, в этом — 500. На сколько процентов вырос приезд?',s:['Прирост = (500 − 400) / 400 × 100%','= 100 / 400 × 100% = 25%']},
 gen:[[
  ()=>{const n=R(4,6),m=pick([60,80,100,120,150,200,250,300]),k=m>=150?10:5;for(;;){const v=Array.from({length:n-1},()=>m+k*R(-6,6)),x=n*m-pzSum(v);if(x<m*.4||x>m*1.6)continue;v.push(x);
    return pzQ(`Выручка ${n} лавок на торгу за день: ${nl(v)} руб. Какова средняя выручка одной лавки?`,m,'rub',[`Сумма: ${v.map(x=>nf(x)).join(' + ')} = ${nf(n*m)}`,`Среднее = ${nf(n*m)} / ${n} = ${nf(m)} руб.`])}},
  ()=>{const n=pick([5,7]);let v;do v=Array.from({length:n},()=>5*R(8,60));while(new Set(v).size<n);const o=[...v].sort((a,b)=>a-b),md=o[(n-1)/2];
    return pzQ(`Гостей на ярмарке по дням: ${nl(v)}. Найди медиану.`,md,U_GOST,[`Упорядочим: ${nl(o)}`,`Посередине ${(n+1)/2}-е число из ${n}: медиана = ${nf(md)}`])},
  ()=>{const N=pick([400,500,600,800,1000,1200,1500,2000]),p=pick([5,10,15,20,25,30,40,45,60,75]),k=N*p/100,[w,w1]=pick([['держат корову','держит корову'],['платят оброк вовремя','платит оброк вовремя'],['топят по-белому','топит по-белому'],['ездят на ярмарку','ездит на ярмарку']]);
    return pzQ(`В ${pick(PZ_SLOB)} слободе ${nf(N)} дворов, из них ${nf(k)} ${w}. Какая доля дворов ${w1}?`,p,'pct',[`Доля = ${nf(k)} / ${nf(N)} × 100%`,`= ${np(p)}`])},
  ()=>{const o=pick([200,300,400,500,800,1000,1200,1500]),g=pick([10,20,25,30,40,50,-10,-20,-25,-40]),n=o*(1+g/100);
    return pzQ(`В прошлом году на Покровскую ярмарку приехало ${nf(o)} купцов, в этом — ${nf(n)}. На сколько процентов ${g>0?'вырос':'упал'} приезд купцов?`,Math.abs(g),'pct',
      [`Прирост = (${nf(n)} − ${nf(o)}) / ${nf(o)} × 100%`,`= ${nf(n-o)} / ${nf(o)} × 100% = ${np(g)}`,...(g<0?[`Минус — значит, упал на ${np(-g)}`]:[])],{abs:1})},
  ()=>{const V=pick([200,300,400,500,600,800,1000]),c=pick([2,3,4,5,6,8,10,12,15]),k=V*c/100;
    return pzQ(`В A/B-тесте глашатай кричал два разных зазыва. Зазыв «Б» услышали ${nf(V)} прохожих, ${k} из них купили. Какова конверсия зазыва «Б»?`,c,'pct',[`Конверсия = ${k} / ${nf(V)} × 100% = ${np(c)}`])},
 ],[
  ()=>{const m=pick([200,250,300,400,500]);for(;;){const v=Array.from({length:4},()=>m+10*R(-8,8)),s=pzSum(v),x=5*m-s;if(x<m*.5||x>m*1.5)continue;
    return pzQ(`Средняя выручка пяти лавок за день — ${nr(m)} Четыре из них выручили ${nl(v)} руб. Сколько выручила пятая?`,x,'rub',
      [`(${v.map(x=>nf(x)).join(' + ')} + x) / 5 = ${nf(m)}`,`${nf(s)} + x = ${nf(5*m)}`,`x = ${nf(5*m)} − ${nf(s)} = ${nf(x)} руб.`])}},
  ()=>{const m1=pick([60,80,100,120,150]),d=pick([4,5,6,8,10]),n=pick([3,4,5]),m2=m1+d,x=(n+1)*m2-n*m1;
    return pzQ(`За ${n} ${pzPl(n,'день','дня','дней')} ярмарки приходило в среднем ${m1} гостей в день. Сколько гостей нужно в следующий день, чтобы среднее за ${n+1} ${pzPl(n+1,'день','дня','дней')} стало ${m2}?`,x,U_GOST,
      [`(${n} × ${m1} + x) / ${n+1} = ${m2}`,`${n*m1} + x = ${(n+1)*m2}`,`x = ${(n+1)*m2} − ${n*m1} = ${x}`])},
  ()=>{const N=pick([400,500,600,800,1000,1200,1500,2000]),p=pick([5,10,15,20,25,30,40,60,75]),k=N*p/100;
    return pzQ(`Корову держат ${p}% дворов ${pick(PZ_SLOB)} слободы — это ${nf(k)} ${pzPl(k,'двор','двора','дворов')}. Сколько всего дворов в слободе?`,N,U_DV,
      [`${p}% от x = ${nf(k)}: ${nf(p/100)} · x = ${nf(k)}`,`x = ${nf(k)} / ${nf(p/100)} = ${nf(N)}`])},
  ()=>{const o=pick([200,400,500,800,1000,1200]),g=pick([10,20,25,50,-10,-20,-25]),n=o*(1+g/100),k=1+g/100;
    return pzQ(`Приезд купцов на ярмарку ${g>0?'вырос':'упал'} на ${Math.abs(g)}% и составил ${nf(n)}. Сколько купцов приезжало в прошлом году?`,o,U_KUP,
      [`x · (1 ${g>0?'+':'−'} ${nf(Math.abs(g)/100)}) = ${nf(n)}`,`${nf(k)} · x = ${nf(n)}`,`x = ${nf(n)} / ${nf(k)} = ${nf(o)}`])},
  ()=>{const cA=pick([2,3,4,5,6,8]),d=pick([1,2,3,4]),V=pick([200,300,400,500,600,800,1000]),k=V*(cA+d)/100;
    return pzQ(`A/B-тест: зазыв «А» дал конверсию ${cA}%. Зазыв «Б» услышат ${nf(V)} прохожих. Сколько покупок должен дать «Б», чтобы его конверсия была на ${d} п. п. выше, чем у «А»?`,k,U_BUY,
      [`Нужная конверсия: ${cA}% + ${d} п. п. = ${cA+d}%`,`x / ${nf(V)} = ${nf((cA+d)/100)}`,`x = ${nf(V)} · ${nf((cA+d)/100)} = ${k}`])},
 ],[
  ()=>{const[s1,s2]=pzPick2(PZ_SLOB),n1=pick([100,200,300,400,500]),n2=pick([100,200,300,400,500,600]);let m1,m2;do{m1=pick([20,25,30,40,50]);m2=pick([30,35,40,45,60,80])}while(m1===m2);
    const t=n1*m1+n2*m2,a=t/(n1+n2);
    return pzQ(`В ${s1} слободе ${n1} дворов, средний оброк — ${nr(m1)} В ${s2} — ${n2} дворов, средний оброк ${nr(m2)} Каков средний оброк по обеим слободам вместе?`,a,'rub',
      [`Всего оброка: ${n1} × ${m1} + ${n2} × ${m2} = ${nf(n1*m1)} + ${nf(n2*m2)} = ${nf(t)} руб.`,`Всего дворов: ${n1} + ${n2} = ${n1+n2}`,`Среднее = ${nf(t)} / ${n1+n2} ${pzEq(a)} руб.`,'Простое среднее двух оброков тут не годится: дворов в слободах разное число.'])},
  ()=>{for(;;){const v=Array.from({length:5},()=>10*R(10,40));v.push(10*R(80,150));const s=pzSum(v);if(s%6)continue;pzShuf(v);const o=[...v].sort((a,b)=>a-b),md=(o[2]+o[3])/2,mn=s/6;if(mn<=md)continue;
    return pzQ(`Выручка шести лавок за день: ${nl(v)} руб. На сколько рублей средняя выручка больше медианы?`,mn-md,'rub',
      [`Упорядочим: ${nl(o)}`,`Медиана = (${o[2]} + ${o[3]}) / 2 = ${nf(md)}`,`Среднее = ${nf(s)} / 6 = ${nf(mn)}`,`Разница: ${nf(mn)} − ${nf(md)} = ${nf(mn-md)} руб.`,'Одна богатая лавка тянет среднее вверх, а медиана её не замечает.'])}},
  ()=>{const[cA,cB]=pick([[4,5],[4,6],[5,6],[5,7],[5,8],[8,10],[8,12],[10,12],[10,15],[6,9],[6,8],[2,3]]),VA=pick([200,300,400,500,600,800,1000]),VB=pick([200,300,400,500,600,800,1000]),
      kA=VA*cA/100,kB=VB*cB/100,up=(cB-cA)/cA*100;
    return pzQ(`A/B-тест зазывов. Зазыв «А» услышали ${nf(VA)} прохожих, купили ${kA}. Зазыв «Б» услышали ${nf(VB)}, купили ${kB}. На сколько процентов конверсия «Б» выше конверсии «А»? Не в пунктах, а в процентах от конверсии «А».`,up,'pct',
      [`Конверсия «А» = ${kA} / ${nf(VA)} = ${cA}%`,`Конверсия «Б» = ${kB} / ${nf(VB)} = ${cB}%`,`Разница: ${cB-cA} п. п.`,`Прирост = ${cB-cA} / ${cA} × 100% ${pzEq(up)}%`])},
  ()=>{for(;;){const g1=pick([10,20,25,50,-10,-20]),g2=pick([10,20,25,50,-10,-20,-50]),m=(1+g1/100)*(1+g2/100),t=(m-1)*100;if(Math.abs(t)<1e-9)continue;
    const w=g=>g>0?'выросла':'упала';
    return pzQ(`Выручка ярмарки за первый год ${w(g1)} на ${Math.abs(g1)}%, а за второй ${w(g2)} на ${Math.abs(g2)}%. На сколько процентов она ${w(t)} за два года?`,Math.abs(t),'pct',
      [`Множители: ${nf(1+g1/100)} и ${nf(1+g2/100)}`,`За два года: ${nf(1+g1/100)} × ${nf(1+g2/100)} = ${nf(m,4)}`,`${nf(m,4)} − 1 = ${nf(m-1,4)}, то есть ${t>0?'+':''}${np(t)}`,'Проценты не складывают: множители перемножают.'],{abs:1})}},
  ()=>{const N1=pick([400,500,800,1000]),p1=pick([10,20,25,30,40]),d=pick([-10,-5,5,10,15]),p2=p1+d,N2=N1+pick([100,200,300,400]),k2=N2*p2/100;
    return pzQ(`Год назад в ${pick(PZ_SLOB)} слободе было ${nf(N1)} дворов, и ${p1}% из них держали корову. Теперь дворов ${nf(N2)}, а корову держат ${nf(k2)}. На сколько процентных пунктов ${d>0?'выросла':'упала'} доля дворов с коровой?`,Math.abs(d),'pp',
      [`Доля теперь: ${nf(k2)} / ${nf(N2)} × 100% = ${p2}%`,`Было ${p1}%: ${p2} − ${p1} = ${d} п. п.`],{abs:1})},
 ]]},

{id:'fin',name:'Приказ Большой казны',topic:'финансы и экономика',what:'маржа, наценка, точка безубыточности, простые и сложные проценты, подати',
 dyak:'Я в Большой казне — дьяк: / рубль к рублю кладу вот так.',
 tsar:'В Большой казне — то пусто, то густо: / разберись, отчего так грустно.',
 rules:['<b>Маржа</b> = (цена − себестоимость) / цена × 100% — какая доля цены остаётся купцу.','<b>Наценка</b> = (цена − себестоимость) / себестоимость × 100% — сколько накинули сверху. Наценка всегда больше маржи.',
  '<b>Точка безубыточности</b> = постоянные расходы / (цена − переменные расходы на штуку) — сколько штук продать, чтобы выйти в ноль. Постоянные — аренда и жалованье, переменные — сырьё на каждую штуку.',
  '<b>Простые проценты</b>: итог = вклад × (1 + ставка × лет).','<b>Сложные проценты</b>: итог = вклад × (1 + ставка)<sup>лет</sup> — проценты каждый год начисляются и на прежние проценты.',
  '<b>Подать</b> (налог): подать = доход × ставка, останется = доход × (1 − ставка).'],
 ex:{q:'Сапожник тратит на пару сапог 300 руб., а продаёт её за 400. Найди маржу и наценку.',s:['Прибыль с пары: 400 − 300 = 100 руб.','Маржа = 100 / 400 × 100% = 25%','Наценка = 100 / 300 × 100% ≈ 33,3%']},
 gen:[[
  ()=>{const G=pick(PZ_GOODS),m=pick([10,20,25,40,50]),p=pick([200,300,400,500,600,800,1000,1200,1500,2000]),c=p*(1-m/100);
    return pzQ(`${pzCap(G.m)} тратит на ${G.a} ${nr(c)}, а продаёт ${G.pr} за ${nr(p)} Какова маржа?`,m,'pct',[`Маржа = (${nf(p)} − ${nf(c)}) / ${nf(p)} × 100%`,`= ${nf(p-c)} / ${nf(p)} × 100% = ${m}%`])},
  ()=>{const G=pick(PZ_GOODS),c=pick([100,200,300,400,500,600,800]),k=pick([10,20,25,30,40,50,60,75,100]),p=c*(1+k/100);
    return pzQ(`${pzCap(G.m)} тратит на ${G.a} ${nr(c)}, а продаёт ${G.pr} за ${nr(p)} Какова наценка?`,k,'pct',[`Наценка = (${nf(p)} − ${nf(c)}) / ${nf(c)} × 100%`,`= ${nf(p-c)} / ${nf(c)} × 100% = ${k}%`])},
  ()=>{const B=pick(PZ_BE),v=pick(B.v),d=pick(B.d),u=pick([200,300,400,500,600,800,1000,1200]),F=u*d,p=v+d;
    return pzQ(`${B.who} платит за аренду и жалованье ${nr(F)} в месяц. ${B.it} продаётся за ${nr(p)}, ${B.mat} ${B.on} стоят ${nr(v)} Сколько ${B.f[2]} в месяц нужно продать, чтобы выйти в ноль?`,u,[B.ph,...B.f],
      [`С каждой штуки остаётся: ${p} − ${v} = ${d} руб.`,`Точка безубыточности = ${nf(F)} / ${d} = ${nf(u)}`])},
  ()=>{const P0=pick([1000,2000,3000,5000,10000]),r=pick([5,8,10,12,15,20]),n=R(2,5),A=P0*(1+r/100*n);
    return pzQ(`Купец отдал в рост ${nr(P0)} под ${r}% годовых, простые проценты. Сколько ему вернут через ${n} ${pzPl(n,'год','года','лет')} вместе с процентами?`,A,'rub',
      [`Итог = ${nf(P0)} × (1 + ${nf(r/100)} × ${n})`,`= ${nf(P0)} × ${nf(1+r/100*n)} = ${nf(A)} руб.`])},
  ()=>{for(;;){const P0=pick([1000,2000,3000,4000,5000,8000,10000,20000]),r=pick([5,10,20]),n=pick([2,2,3]),k=(1+r/100)**n,A=P0*k;if(pzDec(A)>0)continue;
    return pzQ(`Купец положил в казну ${nr(P0)} под ${r}% годовых. Проценты каждый год прибавляются к вкладу (сложные проценты). Сколько будет на вкладе через ${n} ${pzPl(n,'год','года','лет')}?`,A,'rub',
      [`Итог = ${nf(P0)} × ${nf(1+r/100)}${pzSup(n)}`,`= ${nf(P0)} × ${nf(k,4)} = ${nf(A)} руб.`])}},
  ()=>{const I=1000*pick([20,30,40,50,60,80,100,120]),t=pick([6,10,13,15,20]),x=I*t/100,left=R(0,1);
    return pzQ(`Купец заработал за год ${nr(I)} Подать — ${t}% с дохода. ${left?'Сколько у него останется после подати?':'Сколько подати он заплатит?'}`,left?I-x:x,'rub',
      [`Подать = ${nf(I)} × ${nf(t/100)} = ${nf(x)} руб.`,...(left?[`Останется: ${nf(I)} − ${nf(x)} = ${nf(I-x)} руб.`]:[])])},
 ],[
  ()=>{const G=pick(PZ_GOODS),m=pick([10,20,25,40,50]),p=pick([200,300,400,500,600,800,1000,1200,1500,2000]),c=p*(1-m/100);
    return pzQ(`${pzCap(G.m)} тратит на ${G.a} ${nr(c)} По какой цене продавать, чтобы маржа была ${m}%?`,p,'rub',
      [`(x − ${nf(c)}) / x = ${nf(m/100)}`,`x − ${nf(c)} = ${nf(m/100)}x`,`${nf(1-m/100)}x = ${nf(c)}`,`x = ${nf(c)} / ${nf(1-m/100)} = ${nf(p)} руб.`])},
  ()=>{const G=pick(PZ_GOODS),c=pick([100,200,300,400,500,600,800]),k=pick([10,20,25,40,50,60,75,100]),p=c*(1+k/100);
    return pzQ(`${pzCap(G.n)} продаётся за ${nr(p)} с наценкой ${k}%. Сколько тратит на ${G.pr==='его'?'него':'неё'} ${G.m}?`,c,'rub',
      [`x · (1 + ${nf(k/100)}) = ${nf(p)}`,`${nf(1+k/100)}x = ${nf(p)}`,`x = ${nf(p)} / ${nf(1+k/100)} = ${nf(c)} руб.`])},
  ()=>{const B=pick(PZ_BE),v=pick(B.v),d=pick(B.d),u=pick([200,300,400,500,600,800,1000]),F=u*d,p=v+d;
    return pzQ(`${B.who} платит за аренду и жалованье ${nr(F)} в месяц, ${B.mat} на ${B.one} стоят ${nr(v)} В месяц удаётся продать ${nf(u)} ${pzPl(u,...B.f)}. По какой цене продавать, чтобы выйти в ноль?`,p,'rub',
      [`${nf(u)} · (x − ${v}) = ${nf(F)}`,`x − ${v} = ${nf(F)} / ${nf(u)} = ${d}`,`x = ${d} + ${v} = ${p} руб.`])},
  ()=>{const P0=pick([1000,2000,4000,5000,10000]),r=pick([5,8,10,12,15,20]),n=R(2,5),A=P0*(1+r/100*n);
    return pzQ(`Купец отдал в рост ${nr(P0)} под простые проценты, и через ${n} ${pzPl(n,'год','года','лет')} ему вернули ${nr(A)} Какая была ставка годовых?`,r,'pct',
      [`${nf(P0)} · (1 + ${n}x) = ${nf(A)}`,`1 + ${n}x = ${nf(A)} / ${nf(P0)} = ${nf(A/P0)}`,`${n}x = ${nf(A/P0-1)}`,`x = ${nf(r/100)}, то есть ${r}%`])},
  ()=>{for(;;){const P0=pick([1000,2000,3000,4000,5000,8000,10000,20000]),r=pick([5,10,20]),k=(1+r/100)**2,A=P0*k;if(pzDec(A)>0)continue;
    return pzQ(`Купец положил деньги в казну под ${r}% годовых, сложные проценты. Через 2 года на вкладе стало ${nr(A)} Сколько он положил?`,P0,'rub',
      [`x · ${nf(1+r/100)}² = ${nf(A)}`,`${nf(k,4)}x = ${nf(A)}`,`x = ${nf(A)} / ${nf(k,4)} = ${nf(P0)} руб.`])}},
  ()=>{const t=pick([10,13,15,20]),G0=1000*pick([20,30,40,50,60,80,100]),N=G0*(1-t/100);
    return pzQ(`Купцу нужно, чтобы после подати ${t}% с дохода у него осталось ${nr(N)} Сколько он должен заработать?`,G0,'rub',
      [`x − ${nf(t/100)}x = ${nf(N)}`,`${nf(1-t/100)}x = ${nf(N)}`,`x = ${nf(N)} / ${nf(1-t/100)} = ${nf(G0)} руб.`])},
 ],[
  ()=>{for(;;){const Rv=1000*R(20,60),C=1000*Math.round(Rv*pick([.4,.5,.6])/1000),F=1000*R(2,8),pr=Rv-C-F;if(pr<=0)continue;const t=pick([10,13,15,20]),x=pr*t/100;
    return pzQ(`Лавка за месяц выручила ${nr(Rv)} Товар для неё стоил ${nr(C)}, аренда и жалованье — ${nr(F)} Подать — ${t}% с прибыли. Сколько чистой прибыли осталось?`,pr-x,'rub',
      [`Прибыль до подати: ${nf(Rv)} − ${nf(C)} − ${nf(F)} = ${nf(pr)} руб.`,`Подать: ${nf(pr)} × ${nf(t/100)} = ${nf(x)} руб.`,`Чистая прибыль: ${nf(pr)} − ${nf(x)} = ${nf(pr-x)} руб.`])}},
  ()=>{const k=pick([20,25,30,40,50,60,75,80,100,120,150,200,300]),m=k/(100+k)*100;
    return pzQ(`Купец ставит наценку ${k}% на все товары. Какая у него маржа?`,m,'pct',
      [`Пусть товар стоит купцу 100 руб., тогда цена — ${100+k} руб.`,`Прибыль с товара: ${k} руб.`,`Маржа = ${k} / ${100+k} × 100% ${pzEq(m)}%`])},
  ()=>{const B=pick(PZ_BE),v=pick(B.v),d=pick(B.d),u=pick([200,300,400,500,600,800]),F=u*d,p=v+d,T=d*pick([100,200,300,400]),x=(F+T)/d;
    return pzQ(`${B.who} платит за аренду и жалованье ${nr(F)} в месяц. ${B.it} продаётся за ${nr(p)}, ${B.mat} ${B.on} стоят ${nr(v)} Сколько ${B.f[2]} нужно продать за месяц, чтобы прибыль была ${nf(T)} руб.?`,x,[B.ph,...B.f],
      [`С каждой штуки остаётся: ${p} − ${v} = ${d} руб.`,`Нужно покрыть: ${nf(F)} + ${nf(T)} = ${nf(F+T)} руб.`,`${nf(F+T)} / ${d} = ${nf(x)}`])},
  ()=>{const P0=pick([1000,2000,3000,5000,10000]),r=pick([5,6,8,12,15]),k=1+r/100,a1=P0*k,a2=a1*k,a3=a2*k;
    return pzQ(`Купец положил в казну ${nr(P0)} под ${r}% годовых, сложные проценты. Сколько будет на вкладе через 3 года?`,a3,'rub',
      [`Через год: ${nf(P0)} × ${nf(k)} = ${nf(a1)}`,`Через два: ${nf(a1)} × ${nf(k)} = ${nf(a2)}`,`Через три: ${nf(a2)} × ${nf(k)} = ${nf(a3)}`,`≈ ${nf(a3,0)} руб.`],{r:0,tol:1.5})},
  ()=>{const P0=1000*pick([1,2,5,10,20]),r=pick([10,20]),n=pick([2,3]),A1=P0*(1+r/100*n),A2=P0*(1+r/100)**n;
    return pzQ(`Купец выбирает: положить ${nr(P0)} под ${r}% годовых с простыми процентами или со сложными. На сколько больше он получит через ${n} ${pzPl(n,'год','года','лет')} со сложными?`,A2-A1,'rub',
      [`Простые: ${nf(P0)} × (1 + ${nf(r/100)} × ${n}) = ${nf(A1)}`,`Сложные: ${nf(P0)} × ${nf(1+r/100)}${pzSup(n)} = ${nf(A2)}`,`Разница: ${nf(A2)} − ${nf(A1)} = ${nf(A2-A1)} руб.`])},
  ()=>{for(;;){const G=pick(PZ_GOODS),p=pick([200,400,500,600,800,1000]),c=p*pick([.5,.6,.7]),ds=pick([10,20,25]),p2=p*(1-ds/100),m=(p2-c)/p2*100;if(m<=0)continue;
    return pzQ(`${pzCap(G.m)} тратит на ${G.a} ${nr(c)}, а продаёт ${G.pr} за ${nr(p)} На ярмарке он даёт скидку ${ds}%. Какая у него маржа на ярмарке?`,m,'pct',
      [`Цена со скидкой: ${nf(p)} × ${nf(1-ds/100)} = ${nf(p2)} руб.`,`Маржа = (${nf(p2)} − ${nf(c)}) / ${nf(p2)} × 100%`,`= ${nf(p2-c)} / ${nf(p2)} × 100% ${pzEq(m)}%`])}},
 ]]},

{id:'prod',name:'Приказ Большого прихода',topic:'продуктовые метрики',what:'ARPU, ARPPU, конверсия, удержание, отток, LTV',
 dyak:'Я дьяк Большого прихода: / знаю, сколько с двора дохода.',
 tsar:'Подать с дворов течёт рекой — / да мелкой, а не той какой!',
 rules:['<b>ARPU</b> — средний доход на одного: выручка / все дворы (и платящие, и нет).','<b>ARPPU</b> — средний доход на платящего: выручка / платящие дворы.',
  '<b>Конверсия в оплату</b> = платящие / все × 100%. Отсюда ARPU = конверсия × ARPPU.',
  '<b>Удержание</b> = сколько осталось через срок / сколько было × 100%.','<b>Отток</b> = ушли за месяц / было в начале месяца × 100%. Удержание + отток = 100%.',
  '<b>LTV</b> — сколько денег двор приносит за всё время: платёж в месяц × сколько месяцев он остаётся. Средний срок ≈ 1 / отток: при оттоке 10% двор живёт 10 месяцев.'],
 ex:{q:'В слободе 1200 дворов, платят водовозу 300, собрано 9000 руб. Найди ARPU и ARPPU.',s:['ARPU = 9000 / 1200 = 7,5 руб.','ARPPU = 9000 / 300 = 30 руб.','Проверка: конверсия = 300 / 1200 = 25%, и 25% × 30 = 7,5']},
 gen:[[
  ()=>{const sv=pick(PZ_SVC),N=pick([400,500,800,1000,1200,1500,2000]),a=pick([5,6,7.5,8,10,12,15,20]),Rv=N*a;
    return pzQ(`В ${pick(PZ_SLOB)} слободе ${nf(N)} дворов. За месяц ${sv[0]} собрал с неё ${nr(Rv)} Каков ARPU — средний доход с одного двора?`,a,'rub',[`ARPU = выручка / все дворы = ${nf(Rv)} / ${nf(N)} = ${nf(a)} руб.`])},
  ()=>{const sv=pick(PZ_SVC),N=pick([400,500,800,1000,1200,1500,2000]),c=pick([10,15,20,25,30,40,50]),k=N*c/100,ap=pick([20,25,30,40,50,60]),Rv=k*ap;
    return pzQ(`В ${pick(PZ_SLOB)} слободе ${nf(N)} дворов, платят ${sv[1]} ${nf(k)}, собрано ${nr(Rv)} Каков ARPPU — средний доход с платящего двора?`,ap,'rub',
      [`ARPPU = выручка / платящие = ${nf(Rv)} / ${nf(k)} = ${ap} руб.`,`Все ${nf(N)} дворов тут ни при чём: они нужны для ARPU.`])},
  ()=>{const sv=pick(PZ_SVC),N=pick([400,500,800,1000,1200,1500,2000]),c=pick([5,10,15,20,25,30,40]),k=N*c/100;
    return pzQ(`Из ${nf(N)} дворов ${pick(PZ_SLOB)} слободы ${sv[2]} наняли ${nf(k)}. Какова конверсия в оплату?`,c,'pct',[`Конверсия = ${nf(k)} / ${nf(N)} × 100% = ${c}%`])},
  ()=>{const sv=pick(PZ_SVC),C=pick([200,300,400,500,800,1000]),r=pick([50,60,70,75,80,85,90]),m=C*r/100;
    return pzQ(`В январе ${sv[2]} наняли ${nf(C)} новых дворов, а в феврале из них продолжили платить ${nf(m)}. Каково удержание за месяц?`,r,'pct',[`Удержание = ${nf(m)} / ${nf(C)} × 100% = ${r}%`])},
  ()=>{const sv=pick(PZ_SVC),S0=pick([200,400,500,800,1000,1200]),c=pick([2,4,5,8,10,15,20]),L=S0*c/100;
    return pzQ(`В начале месяца ${sv[1]} платили ${nf(S0)} дворов, за месяц ${L} ${pzPl(L,'двор отказался','двора отказались','дворов отказались')}. Каков отток за месяц?`,c,'pct',[`Отток = ${L} / ${nf(S0)} × 100% = ${c}%`])},
  ()=>{const sv=pick(PZ_SVC),p=pick([20,25,30,40,50,60]),T=pick([4,5,6,8,10,12,18,24]);
    return pzQ(`Двор платит ${sv[1]} ${nr(p)} в месяц и в среднем остаётся с ним ${T} ${pzPl(T,'месяц','месяца','месяцев')}. Каков LTV — сколько денег двор приносит за всё время?`,p*T,'rub',[`LTV = ${p} × ${T} = ${nf(p*T)} руб.`])},
 ],[
  ()=>{const sv=pick(PZ_SVC),k=pick([100,150,200,250,300,400,500,600]),ap=pick([20,25,30,40,50,60]),Rv=k*ap;
    return pzQ(`${pzCap(sv[0])} собрал за месяц ${nr(Rv)}, ARPPU — ${nr(ap)} Сколько дворов ему платят?`,k,U_DV,[`${nf(Rv)} / x = ${ap}`,`x = ${nf(Rv)} / ${ap} = ${nf(k)}`])},
  ()=>{const sv=pick(PZ_SVC),N=pick([400,500,800,1000,1200,1500,2000]),a=pick([5,6,7.5,8,10,12,15,20]),Rv=N*a;
    return pzQ(`${pzCap(sv[0])} собрал со слободы ${nr(Rv)}, ARPU вышел ${nr(a)} Сколько дворов в слободе?`,N,U_DV,[`${nf(Rv)} / x = ${nf(a)}`,`x = ${nf(Rv)} / ${nf(a)} = ${nf(N)}`])},
  ()=>{const sv=pick(PZ_SVC),N=pick([400,500,800,1000,1200,1500,2000]),c=pick([5,10,15,20,25,40]),k=N*c/100;
    return pzQ(`Конверсия в оплату у ${sv[2]} — ${c}%. Сколько дворов ему надо обойти, чтобы платящих стало ${nf(k)}?`,N,U_DV,[`x · ${nf(c/100)} = ${nf(k)}`,`x = ${nf(k)} / ${nf(c/100)} = ${nf(N)}`])},
  ()=>{const sv=pick(PZ_SVC),S0=pick([200,400,500,800,1000,1200]),c=pick([2,4,5,8,10,15,20]),L=S0*c/100;
    return pzQ(`За месяц от ${sv[2]} ${pzPl(L,'ушёл','ушли','ушли')} ${L} ${pzPl(L,'двор','двора','дворов')}, отток — ${c}%. Сколько дворов платило ему в начале месяца?`,S0,U_DV,[`${L} / x = ${nf(c/100)}`,`x = ${L} / ${nf(c/100)} = ${nf(S0)}`])},
  ()=>{const sv=pick(PZ_SVC),C=pick([200,300,400,500,800,1000]),r=pick([50,60,70,75,80,90]),m=C*r/100;
    return pzQ(`Удержание у ${sv[2]} — ${r}% за месяц. Сколько новых дворов нужно привлечь в январе, чтобы в феврале из них платили ${nf(m)}?`,C,U_DV,[`x · ${nf(r/100)} = ${nf(m)}`,`x = ${nf(m)} / ${nf(r/100)} = ${nf(C)}`])},
  ()=>{const sv=pick(PZ_SVC),p=pick([20,25,30,40,50,60]),T=pick([4,5,6,8,10,12,18,24]),L=p*T;
    return R(0,1)?pzQ(`LTV двора у ${sv[2]} — ${nr(L)}, а платит двор ${nr(p)} в месяц. Сколько месяцев в среднем двор остаётся с ${sv[0]}ом?`,T,'mon',[`${p} · x = ${nf(L)}`,`x = ${nf(L)} / ${p} = ${T} мес.`])
      :pzQ(`${pzCap(sv[0])} хочет, чтобы LTV двора был ${nr(L)}, а двор в среднем остаётся ${T} ${pzPl(T,'месяц','месяца','месяцев')}. Сколько брать с двора в месяц?`,p,'rub',[`x · ${T} = ${nf(L)}`,`x = ${nf(L)} / ${T} = ${p} руб.`])},
 ],[
  ()=>{const sv=pick(PZ_SVC),N=pick([500,800,1000,1200,2000]),c=pick([10,15,20,25,30,40]),ap=pick([20,30,40,50,60]),k=N*c/100,Rv=k*ap,a=Rv/N;
    return pzQ(`В ${pick(PZ_SLOB)} слободе ${nf(N)} дворов. ${pzCap(sv[2])} наняли ${c}% из них, и каждый платящий двор платит в среднем ${nr(ap)} в месяц. Каков ARPU?`,a,'rub',
      [`Платящих: ${nf(N)} × ${nf(c/100)} = ${nf(k)}`,`Выручка: ${nf(k)} × ${ap} = ${nf(Rv)} руб.`,`ARPU = ${nf(Rv)} / ${nf(N)} = ${nf(a)} руб. (то же, что ${c}% × ${ap})`])},
  ()=>{const sv=pick(PZ_SVC),p=pick([20,30,40,50,60,80]),c=pick([4,5,8,10,20,25]),T=100/c,L=p*T;
    return pzQ(`Двор платит ${sv[1]} ${nr(p)} в месяц, отток — ${c}% в месяц. Каков LTV двора?`,L,'rub',[`Средний срок жизни двора: 1 / ${nf(c/100)} = ${nf(T)} мес.`,`LTV = ${p} × ${nf(T)} = ${nf(L)} руб.`])},
  ()=>{const sv=pick(PZ_SVC),C=pick([1000,2000,5000]),r=pick([50,60,70,80,90]),n=pick([2,3]),st=[];let v=C;
    for(let i=1;i<=n;i++){const w=v*r/100;st.push(`Через ${i} ${pzPl(i,'месяц','месяца','месяцев')}: ${nf(v)} × ${nf(r/100)} = ${nf(w)}`);v=w}
    return pzQ(`${pzCap(sv[2])} наняли ${nf(C)} новых дворов. Каждый месяц продолжают платить ${r}% тех, кто платил в прошлом месяце. Сколько дворов из них будет платить через ${n} ${pzPl(n,'месяц','месяца','месяцев')}?`,v,U_DV,st)},
  ()=>{const sv=pick(PZ_SVC),P0=pick([200,300,400,500,800,1000]),c=pick([5,10,20]),nw=pick([20,30,40,50,60,80,100]),ap=pick([20,30,40,50]),stay=P0*(1-c/100),P1=stay+nw;
    return pzQ(`${pzCap(sv[1])} платят ${nf(P0)} дворов по ${nr(ap)} в месяц. Отток — ${c}% в месяц, а новых дворов приходит ${nw} в месяц. Какая выручка будет в следующем месяце?`,P1*ap,'rub',
      [`Останутся: ${nf(P0)} × ${nf(1-c/100)} = ${nf(stay)}`,`С новыми: ${nf(stay)} + ${nw} = ${nf(P1)}`,`Выручка: ${nf(P1)} × ${ap} = ${nf(P1*ap)} руб.`])},
  ()=>{const sv=pick(PZ_SVC),N=pick([500,800,1000,1200,2000]),c=pick([10,20,25,40,50]),k=N*c/100,ap=pick([20,30,40,50,60]),Rv=k*ap;
    return pzQ(`В ${pick(PZ_SLOB)} слободе ${nf(N)} дворов, ${sv[0]} собрал с неё за месяц ${nr(Rv)}, конверсия в оплату — ${c}%. Каков ARPPU?`,ap,'rub',
      [`Платящих: ${nf(N)} × ${nf(c/100)} = ${nf(k)}`,`ARPPU = ${nf(Rv)} / ${nf(k)} = ${ap} руб.`])},
 ]]},

{id:'mark',name:'Посольский приказ',topic:'маркетинг',what:'ROI, ROMI, CAC, CPA, CTR, ДРР',
 dyak:'Я дьяк Посольского приказа: / глашатаям считаю каждую фразу.',
 tsar:'Глашатаи орут весь день, / а покупать народу лень!',
 rules:['<b>CTR</b> = зашли в лавку (клики) / увидели зазыв (показы) × 100%.','<b>CPA</b> = расходы на зазыв / число целевых действий (заказов, покупок).',
  '<b>CAC</b> = все расходы на привлечение (зазыв, приказчики) / число новых покупателей.',
  '<b>ROMI</b> = (валовая прибыль с зазыва − расходы на зазыв) / расходы × 100%. Валовая прибыль = выручка − себестоимость товара = выручка × маржа. ROMI 0% — зазыв только окупился, минус — в убыток.',
  '<b>ROI</b> — то же для любых вложений: (доход − вложения) / вложения × 100%.','<b>ДРР</b> (доля рекламных расходов) = расходы на зазыв / выручка с него × 100%.'],
 ex:{q:'Глашатаи стоили 2000 руб., продажи через них дали валовую прибыль 5000 руб. Каков ROMI?',s:['ROMI = (5000 − 2000) / 2000 × 100%','= 3000 / 2000 × 100% = 150%']},
 gen:[[
  ()=>{const I=pick([2000,4000,5000,8000,10000,20000]),c=pick([.5,1,1.5,2,2.5,3,4,5]),k=I*c/100,[w,g]=pick([['Лубок с зазывом на торгу увидели','лубка'],['Глашатая на площади услышали','глашатая']]);
    return pzQ(`${w} ${nf(I)} человек, в лавку зашли ${k}. Каков CTR ${g}?`,c,'pct',[`CTR = ${k} / ${nf(I)} × 100% = ${np(c)}`])},
  ()=>{const cpa=pick([20,25,30,40,50,60,80,100]),n=pick([20,25,30,40,50,60,80,100]),C=cpa*n,[w,v]=pick([['Глашатаи','принесли'],['Скоморохи на ярмарке','принесли'],['Лубки на торгу','принесли']]);
    return pzQ(`${w} обошлись в ${nr(C)} и ${v} ${n} ${pzPl(n,'заказ','заказа','заказов')}. Каков CPA — цена одного заказа?`,cpa,'rub',[`CPA = ${nf(C)} / ${n} = ${cpa} руб.`])},
  ()=>{const cac=pick([40,50,60,80,100,120,150]),n=pick([20,30,40,50,60,80]),T=cac*n,C2=10*Math.round(T*pick([.2,.25,.3,.4])/10),C1=T-C2;
    return pzQ(`На скоморохов потратили ${nr(C1)}, приказчикам за новых покупателей заплатили ${nr(C2)} Пришло ${n} новых покупателей. Каков CAC?`,cac,'rub',
      [`Расходы на привлечение: ${nf(C1)} + ${nf(C2)} = ${nf(T)} руб.`,`CAC = ${nf(T)} / ${n} = ${cac} руб.`])},
  ()=>{const C=pick([1000,2000,3000,4000,5000]),rm=pick([-50,-20,20,50,100,150,200,300]),G=C*(1+rm/100);
    return pzQ(`Глашатаи стоили ${nr(C)} Продажи через них дали валовую прибыль ${nr(G)} Каков ROMI?`,rm,'pct',
      [`ROMI = (${nf(G)} − ${nf(C)}) / ${nf(C)} × 100%`,`= ${nf(G-C)} / ${nf(C)} × 100% = ${np(rm)}`,...(rm<0?['Минус — глашатаи не окупились.']:[])])},
  ()=>{const I=1000*pick([10,20,40,50,100]),roi=pick([10,15,20,25,30,40,50]),Rt=I*(1+roi/100),w=pick(['новую мельницу','лавку на торгу','торговую ладью']);
    return pzQ(`Купец вложил ${nr(I)} в ${w}. За год вложение принесло ${nr(Rt)} дохода. Каков ROI за год?`,roi,'pct',[`ROI = (${nf(Rt)} − ${nf(I)}) / ${nf(I)} × 100%`,`= ${nf(Rt-I)} / ${nf(I)} × 100% = ${roi}%`])},
  ()=>{const d=pick([2,4,5,8,10,12,15,20,25]),Rv=1000*pick([10,20,30,40,50,60,80,100]),C=Rv*d/100;
    return pzQ(`На лубки потратили ${nr(C)}, а выручка с покупателей, что пришли по ним, — ${nr(Rv)} Какова ДРР?`,d,'pct',[`ДРР = ${nf(C)} / ${nf(Rv)} × 100% = ${d}%`])},
 ],[
  ()=>{const C=pick([1000,2000,4000,5000]),rm=pick([25,50,100,150,200,300]),G=C*(1+rm/100);
    return pzQ(`Глашатаи принесут валовую прибыль ${nr(G)} Какой бюджет на глашатаев даст ROMI ${rm}%?`,C,'rub',
      [`(${nf(G)} − x) / x = ${nf(rm/100)}`,`${nf(G)} − x = ${nf(rm/100)}x`,`${nf(G)} = ${nf(1+rm/100)}x`,`x = ${nf(G)} / ${nf(1+rm/100)} = ${nf(C)} руб.`])},
  ()=>{const I=pick([2000,4000,5000,8000,10000,20000]),c=pick([.5,1,2,2.5,4,5]),k=I*c/100;
    return pzQ(`CTR лубка — ${np(c)}. Сколько человек должно его увидеть, чтобы в лавку зашли ${k}?`,I,U_SHOW,[`x · ${nf(c/100,4)} = ${k}`,`x = ${k} / ${nf(c/100,4)} = ${nf(I)}`])},
  ()=>{const cpa=pick([20,25,40,50,80,100]),n=pick([20,25,30,40,50,60,80]),C=cpa*n;
    return pzQ(`Бюджет на скоморохов — ${nr(C)}, а заказ не должен обходиться дороже ${nr(cpa)} Сколько заказов как минимум должны принести скоморохи?`,n,U_ZAK,[`${nf(C)} / x = ${cpa}`,`x = ${nf(C)} / ${cpa} = ${n}`])},
  ()=>{const d=pick([2,4,5,8,10,12,15,20,25]),Rv=1000*pick([10,20,30,40,50,60,80,100]),C=Rv*d/100;
    return pzQ(`Царь велел держать ДРР не выше ${d}%. На глашатаев потратили ${nr(C)} Сколько выручки как минимум они должны принести?`,Rv,'rub',[`${nf(C)} / x = ${nf(d/100)}`,`x = ${nf(C)} / ${nf(d/100)} = ${nf(Rv)} руб.`])},
  ()=>{const I=1000*pick([10,20,40,50,100]),roi=pick([10,20,25,40,50]),Rt=I*(1+roi/100);
    return pzQ(`Мельница принесла за год ${nr(Rt)} дохода, ROI за год — ${roi}%. Сколько в неё вложили?`,I,'rub',
      [`(${nf(Rt)} − x) / x = ${nf(roi/100)}`,`${nf(Rt)} = ${nf(1+roi/100)}x`,`x = ${nf(Rt)} / ${nf(1+roi/100)} = ${nf(I)} руб.`])},
  ()=>{const cac=pick([40,50,60,80,100,120,150]),n=pick([20,30,40,50,60,80]),T=cac*n;
    return pzQ(`Царь отпустил на скоморохов ${nr(T)} Сколько новых покупателей они должны привести, чтобы CAC был ${nr(cac)}?`,n,U_POK,[`${nf(T)} / x = ${cac}`,`x = ${nf(T)} / ${cac} = ${n}`])},
 ],[
  ()=>{for(;;){const I=pick([10000,20000,40000,50000]),c=pick([1,2,2.5,4,5]),k=pick([5,10,20,25]),cl=I*c/100,o=cl*k/100;if(!Number.isInteger(o)||o<4)continue;const cpa=pick([20,25,40,50,80,100]),C=cpa*o;
    return pzQ(`Лубки на торгу увидели ${nf(I)} человек, CTR — ${np(c)}, из зашедших в лавку купили ${k}%. На лубки ушло ${nr(C)} Каков CPA — цена одной покупки?`,cpa,'rub',
      [`Зашли: ${nf(I)} × ${nf(c/100,4)} = ${nf(cl)}`,`Купили: ${nf(cl)} × ${nf(k/100)} = ${nf(o)}`,`CPA = ${nf(C)} / ${nf(o)} = ${cpa} руб.`])}},
  ()=>{for(;;){const C=pick([1000,2000,3000,4000,5000]),m=pick([20,25,40,50]),rm=pick([-20,25,50,100,150,200]),G=C*(1+rm/100),Rv=G*100/m;if(!Number.isInteger(Rv))continue;
    return pzQ(`Глашатаи стоили ${nr(C)} и принесли выручку ${nr(Rv)} Маржа товара — ${m}%. Каков ROMI?`,rm,'pct',
      [`Валовая прибыль: ${nf(Rv)} × ${nf(m/100)} = ${nf(G)} руб.`,`ROMI = (${nf(G)} − ${nf(C)}) / ${nf(C)} × 100% = ${np(rm)}`])}},
  ()=>{let c1,c2;do{c1=pick([40,50,60,80,100]);c2=pick([30,40,50,60,80,120])}while(c1===c2);const n1=pick([20,25,40,50]),n2=pick([20,30,40,50,60]);
    return pzQ(`Глашатаи за ${nr(c1*n1)} привели ${n1} новых покупателей, скоморохи за ${nr(c2*n2)} — ${n2}. На сколько рублей CAC у ${c1<c2?'глашатаев':'скоморохов'} ниже?`,Math.abs(c1-c2),'rub',
      [`CAC глашатаев: ${nf(c1*n1)} / ${n1} = ${c1} руб.`,`CAC скоморохов: ${nf(c2*n2)} / ${n2} = ${c2} руб.`,`Разница: ${Math.max(c1,c2)} − ${Math.min(c1,c2)} = ${Math.abs(c1-c2)} руб.`])},
  ()=>{const[d,m]=pick([[10,50],[20,50],[20,40],[25,50],[10,30],[5,20],[20,30],[15,30],[25,40],[40,50],[10,25],[10,40],[5,25],[8,40],[12,60],[20,60],[30,60],[4,20]]),B=[100,300,1000,3000].find(b=>pzDec(b/d*100*m/100)+pzDec(b/d*100)===0),Rv=B/d*100,G=Rv*m/100,rm=(G-B)/B*100;
    return pzQ(`ДРР лубков — ${d}%, маржа товара — ${m}%. Каков ROMI лубков?`,rm,'pct',
      [`Пусть на лубки ушло ${nf(B)} руб. Тогда выручка: ${nf(B)} / ${nf(d/100)} = ${nf(Rv)} руб.`,`Валовая прибыль: ${nf(Rv)} × ${nf(m/100)} = ${nf(G)} руб.`,`ROMI = (${nf(G)} − ${nf(B)}) / ${nf(B)} × 100% = ${np(rm)}`])},
  ()=>{for(;;){const n=pick([10,20,30,40,50]),c=pick([1,2,4,5]),k=pick([5,10,20,25]),cl=n*100/k,I=Math.round(cl*100/c);if(!Number.isInteger(cl)||Math.abs(I*c/100-cl)>1e-9)continue;const pr=pick([.1,.2,.5,1]),C=I*pr;
    return pzQ(`Один показ лубка стоит ${nf(pr)} руб. CTR — ${c}%, из зашедших в лавку покупает ${k}%. Во сколько обойдётся привлечь ${n} покупателей?`,C,'rub',
      [`Нужно зашедших: ${n} / ${nf(k/100)} = ${nf(cl)}`,`Нужно показов: ${nf(cl)} / ${nf(c/100)} = ${nf(I)}`,`Стоимость: ${nf(I)} × ${nf(pr)} = ${nf(C)} руб.`])}},
  ()=>{const C=pick([1000,2000,3000,4000,5000]),m=pick([20,25,40,50]),Rv=C*100/m;
    return pzQ(`Скоморохи стоят ${nr(C)} Маржа товара — ${m}%. Какую выручку они должны принести, чтобы только окупиться (ROMI = 0%)?`,Rv,'rub',
      [`ROMI = 0, значит, валовая прибыль равна расходам: ${nf(C)} руб.`,`Выручка × ${nf(m/100)} = ${nf(C)}`,`Выручка = ${nf(C)} / ${nf(m/100)} = ${nf(Rv)} руб.`])},
 ]]},

{id:'unit',name:'Купецкий приказ',topic:'юнит-экономика',what:'маржа на единицу, LTV / CAC, окупаемость покупателя',
 dyak:'Я дьяк Купецкого приказа: / считаю барыш с каждого заказа.',
 tsar:'Купцы ко мне идут гурьбой: / «Торгуем, царь, себе в убой!»',
 rules:['<b>Юнит-экономика</b> считает деньги на одну единицу — одну продажу или одного покупателя.','<b>Маржа на единицу</b> = цена − переменные расходы на неё (сырьё, доставка, пошлина с цены).',
  '<b>LTV по марже</b> = маржа с покупателя в месяц × сколько месяцев он остаётся (или маржа с заказа × число заказов).',
  '<b>LTV / CAC</b> — во сколько раз покупатель приносит больше, чем стоит его привлечь. Меньше 1 — в убыток, хорошо — от 3.',
  '<b>Окупаемость покупателя</b> = CAC / маржа с него в месяц — через сколько месяцев он вернёт деньги, потраченные на привлечение.'],
 ex:{q:'Привлечь двор стоит 600 руб., он платит 300 руб. в месяц, маржа — 50%, остаётся 12 месяцев. Найди окупаемость и LTV / CAC.',s:['Маржа в месяц: 300 × 50% = 150 руб.','Окупаемость: 600 / 150 = 4 мес.','LTV = 150 × 12 = 1800 руб.','LTV / CAC = 1800 / 600 = 3']},
 gen:[[
  ()=>{const G=pick(PZ_GOODS),p=pick([300,400,500,600,800,1000]),v1=10*Math.round(p*pick([.4,.5,.6])/10),v2=pick([20,30,40,50]),m=p-v1-v2;
    return pzQ(`${pzCap(G.n)} продаётся за ${nr(p)} Материал и работа стоят ${nr(v1)}, доставка покупателю — ${nr(v2)} Какова маржа на единицу?`,m,'rub',[`Маржа = ${nf(p)} − ${nf(v1)} − ${v2} = ${nf(m)} руб.`])},
  ()=>{const cac=pick([100,200,300,400,500,600]),x=pick([1.5,2,2.5,3,4,5]),L=cac*x;
    return pzQ(`Привлечь нового покупателя в лавку стоит ${nr(cac)} (это CAC), а за всё время он приносит ${nr(L)} маржи (это LTV). Каково отношение LTV / CAC?`,x,'x',
      [`LTV / CAC = ${nf(L)} / ${cac} = ${nf(x)}`,x<3?'Меньше 3 — привлечение дороговато.':'От 3 и выше — привлекать выгодно.'])},
  ()=>{const m=pick([50,75,100,120,150,200,250]),T=pick([2,3,4,5,6,8,10,12]),cac=m*T;
    return pzQ(`Привлечь покупателя стоит ${nr(cac)}, а маржи он приносит ${nr(m)} в месяц. За сколько месяцев он окупится?`,T,'mon',[`Окупаемость = ${nf(cac)} / ${m} = ${T} мес.`])},
  ()=>{const m=pick([40,50,60,80,100,120,150]),k=pick([3,4,5,6,8,10]);
    return pzQ(`С каждого заказа купец получает ${nr(m)} маржи, а покупатель за всё время заказывает в среднем ${k} ${pzPl(k,'раз','раза','раз')}. Каков LTV покупателя по марже?`,m*k,'rub',[`LTV = ${m} × ${k} = ${nf(m*k)} руб.`])},
 ],[
  ()=>{const cac=pick([100,150,200,250,300,400,500]),r=pick([2,3,4,5]),L=cac*r;
    return pzQ(`LTV покупателя — ${nr(L)} Царь велит держать LTV / CAC не ниже ${r}. Сколько можно потратить на привлечение одного покупателя (наибольший CAC)?`,cac,'rub',[`${nf(L)} / x = ${r}`,`x = ${nf(L)} / ${r} = ${cac} руб.`])},
  ()=>{for(;;){const G=pick(PZ_GOODS),t=pick([5,10,20]),p=pick([200,300,400,500,600,800,1000]),v=10*Math.round(p*pick([.4,.5,.6])/10),m=p*(1-t/100)-v;if(m<=0)continue;
    return pzQ(`Пошлина — ${t}% с цены, материал на ${G.a} стоит ${nr(v)} По какой цене продавать, чтобы маржа с каждой штуки была ${nr(m)}?`,p,'rub',
      [`x − ${nf(t/100)}x − ${nf(v)} = ${nf(m)}`,`${nf(1-t/100)}x = ${nf(m+v)}`,`x = ${nf(m+v)} / ${nf(1-t/100)} = ${nf(p)} руб.`])}},
  ()=>{const m=pick([50,75,100,120,150,200,250]),T=pick([2,3,4,5,6,8,10,12]),cac=m*T;
    return pzQ(`Привлечь покупателя стоит ${nr(cac)} Купец хочет, чтобы покупатель окупался за ${T} ${pzPl(T,'месяц','месяца','месяцев')}. Сколько маржи в месяц он должен приносить?`,m,'rub',[`${nf(cac)} / x = ${T}`,`x = ${nf(cac)} / ${T} = ${m} руб.`])},
  ()=>{for(;;){const sv=pick(PZ_SVC),m=pick([20,25,40,50,60,100]),cac=pick([100,150,200,300,400]),r=pick([2,3,4]),T=r*cac/m;if(!Number.isInteger(T)||T>36)continue;
    return pzQ(`Привлечь двор ${sv[1]} обходится в ${nr(cac)}, маржа с двора — ${nr(m)} в месяц. Сколько месяцев двор должен оставаться, чтобы LTV / CAC был ${r}?`,T,'mon',
      [`LTV = ${m} · x`,`${m}x / ${cac} = ${r}`,`${m}x = ${r*cac}`,`x = ${r*cac} / ${m} = ${T} мес.`])}},
  ()=>{const m=pick([50,75,100,120,150,200]),T=pick([3,4,5,6,8,10,12]);
    return pzQ(`Покупатель приносит ${nr(m)} маржи в месяц. Сколько можно тратить на его привлечение, чтобы он окупался за ${T} ${pzPl(T,'месяц','месяца','месяцев')}?`,m*T,'rub',[`x / ${m} = ${T}`,`x = ${m} × ${T} = ${nf(m*T)} руб.`])},
 ],[
  ()=>{for(;;){const sv=pick(PZ_SVC),p=pick([40,60,80,100,120]),M=pick([25,40,50,60]),T=pick([6,10,12,18,24]),mm=p*M/100,L=mm*T,x=pick([1.5,2,2.5,3,4,5]),cac=L/x;if(!Number.isInteger(cac)||!Number.isInteger(mm))continue;
    return pzQ(`Двор платит ${sv[1]} ${nr(p)} в месяц, маржа — ${M}%, и в среднем остаётся ${T} ${pzPl(T,'месяц','месяца','месяцев')}. Привлечь двор стоит ${nr(cac)} Каково отношение LTV / CAC?`,x,'x',
      [`Маржа в месяц: ${p} × ${nf(M/100)} = ${nf(mm)} руб.`,`LTV = ${nf(mm)} × ${T} = ${nf(L)} руб.`,`LTV / CAC = ${nf(L)} / ${nf(cac)} = ${nf(x)}`])}},
  ()=>{const sv=pick(PZ_SVC),p=pick([40,60,80,100,200]),M=pick([25,40,50]),mm=p*M/100,T=pick([3,4,6,8,10,12]),cac=mm*T;
    return pzQ(`Привлечь двор стоит ${nr(cac)} Двор платит ${sv[1]} ${nr(p)} в месяц, маржа — ${M}%. За сколько месяцев двор окупится?`,T,'mon',
      [`Маржа в месяц: ${p} × ${nf(M/100)} = ${nf(mm)} руб.`,`Окупаемость: ${nf(cac)} / ${nf(mm)} = ${T} мес.`])},
  ()=>{for(;;){const p=pick([40,50,60,80,100]),M=pick([40,50,60]),c=pick([4,5,10,20]),mm=p*M/100,L=mm*100/c,x=pick([2,3,4,5]),cac=L/x;if(!Number.isInteger(cac))continue;
    return pzQ(`Двор платит ${nr(p)} в месяц, маржа — ${M}%, отток — ${c}% в месяц. Привлечь двор стоит ${nr(cac)} Каково отношение LTV / CAC?`,x,'x',
      [`Маржа в месяц: ${p} × ${nf(M/100)} = ${nf(mm)} руб.`,`Средний срок: 1 / ${nf(c/100)} = ${100/c} мес.`,`LTV = ${nf(mm)} × ${100/c} = ${nf(L)} руб.`,`LTV / CAC = ${nf(L)} / ${nf(cac)} = ${x}`])}},
  ()=>{for(;;){const n=pick([20,30,40,50,100]),cac=pick([100,150,200,300]),L=cac*pick([1.5,2,3,4]);if(!Number.isInteger(L))continue;const pr=n*(L-cac);
    return pzQ(`Глашатаи привели ${n} покупателей, привлечение каждого обошлось в ${nr(cac)} Каждый покупатель за всё время принесёт ${nr(L)} маржи. Сколько прибыли купцу даст эта когорта?`,pr,'rub',
      [`На привлечение: ${n} × ${cac} = ${nf(n*cac)} руб.`,`Маржа когорты: ${n} × ${nf(L)} = ${nf(n*L)} руб.`,`Прибыль: ${nf(n*L)} − ${nf(n*cac)} = ${nf(pr)} руб.`])}},
  ()=>{for(;;){const m=pick([40,50,60,80,100,120]),k=pick([3,4,5,6]),r=pick([2,3,4]),L=m*k,cac=L/r;if(!Number.isInteger(cac))continue;const n=pick([20,30,40,50]),B=n*cac;
    return pzQ(`С каждого заказа купец получает ${nr(m)} маржи, покупатель заказывает в среднем ${k} ${pzPl(k,'раз','раза','раз')}. Царь требует LTV / CAC не ниже ${r}. Нужно ${n} новых покупателей. Какой наибольший бюджет можно дать глашатаям?`,B,'rub',
      [`LTV = ${m} × ${k} = ${nf(L)} руб.`,`Наибольший CAC: ${nf(L)} / ${r} = ${nf(cac)} руб.`,`Бюджет: ${n} × ${nf(cac)} = ${nf(B)} руб.`])}},
  ()=>{for(;;){const G=pick(PZ_GOODS),p=pick([200,300,400,500,600,800,1000]),t=pick([5,10,20]),v=10*Math.round(p*pick([.3,.4,.5])/10),mm=p*(1-t/100)-v;if(mm<=0)continue;
    const n=pick([20,30,40,50,60,80,100]),F=100*Math.round(n*mm*pick([.3,.5,.6])/100),pr=n*mm-F;if(pr<=0||F<=0)continue;
    return pzQ(`${pzCap(G.m)} продаёт ${G.a} за ${nr(p)} Материал — ${nr(v)} на штуку, пошлина — ${t}% с цены, аренда мастерской — ${nr(F)} в месяц. В месяц он продаёт ${n} штук. Сколько прибыли у него за месяц?`,pr,'rub',
      [`Пошлина со штуки: ${nf(p)} × ${nf(t/100)} = ${nf(p*t/100)} руб.`,`Маржа на единицу: ${nf(p)} − ${nf(p*t/100)} − ${nf(v)} = ${nf(mm)} руб.`,`За месяц: ${n} × ${nf(mm)} − ${nf(F)} = ${nf(pr)} руб.`])}},
 ]]},
];
const PZ_BY=Object.fromEntries(PZ.map(s=>[s.id,s]));
const pzLast={};   // не давать одну и ту же задачу дважды подряд
function pzGen(sec,step){const g=PZ_BY[sec].gen[step],k=sec+step;let i;do i=R(0,g.length-1);while(g.length>1&&i===pzLast[k]);pzLast[k]=i;return{...g[i](),t:i}}

// ---------- проверка ответа: 150%, 150 и 1,5 для процентов; запятая и точка; «руб.», «x =», пробелы в тысячах ----------
function pzNum(inp){let s=inp.toLowerCase().replace(/[−–—]/g,'-').replace(/\s+/g,'');const pct=s.includes('%');
  s=s.replace(/[^0-9.,:/\-]/g,'').replace(/,/g,'.').replace(/^[.:/]+|[.:/]+$/g,'');
  const m=s.match(/^(-?\d+(?:\.\d+)?)(?:[:/](-?\d+(?:\.\d+)?))?$/);if(!m)return null;
  if(m[2]!==undefined&&!+m[2])return null;return{v:m[2]!==undefined?+m[1]/+m[2]:+m[1],pct}}
function pzCheck(p,inp){const r=pzNum(inp);if(!r)return{err:'Не понял число. Пример: 1200, 7,5 или 25%'};
  const tol=Math.max(p.round?.5*10**-p.r:1e-6,p.tol||0)+1e-9,near=x=>Math.abs((p.abs?Math.abs(x):x)-p.a)<=tol;let v=r.v;
  if(p.u==='pct')return{ok:near(v)||!r.pct&&near(v*100)};
  if(p.u==='x'&&r.pct)v/=100;
  return{ok:near(v)}}

// ---------- состояние в сохранении: S.pz ----------
// open — открытые приказы по порядку; st — счёт ступеней {n, ok, r: последние 10}; tut — пройденные уроки дьяка;
// ok — верных поручений царя; rank — чин; task — поручение дня; small — малое поручение; pay — жалованье за сегодня
const pzNew=()=>({open:[],st:{},tut:{},ok:0,rank:0,task:null,small:null,pay:{day:'',g:0}});
function pzFill(){S.pz=Object.assign(pzNew(),S.pz||{})}
const pzSt=(sec,k)=>S.pz.st[sec+k]||(S.pz.st[sec+k]={n:0,ok:0,r:[]});
const pzAcc=q=>q.r.length?pzSum(q.r)/q.r.length:0;
const pzMast=(sec,k)=>{const q=S.pz.st[sec+k];return!!q&&q.ok>=8&&pzAcc(q)>=.7};   // как темы в бою: 8 верных и 70% из последних 10
const pzOpen=sec=>S.pz.open.includes(sec);
const pzUnl=(sec,k)=>!k||pzMast(sec,k-1);
const pzTopStep=sec=>pzMast(sec,1)?2:pzMast(sec,0)?1:0;
function pzRec(sec,k,ok){const q=pzSt(sec,k),was=pzMast(sec,k);q.n++;q.r.push(ok?1:0);if(q.r.length>10)q.r.shift();if(ok)q.ok++;
  if(!was&&pzMast(sec,k))toast(k<2?`${PZ_BY[sec].name}: ступень ${k+1} освоена, открыта ступень ${k+2}`:`${PZ_BY[sec].name} освоен целиком!`)}

// ---------- чины: стольник — 3 верных поручения; воевода — 10 и открыты все приказы; боярин — 25 и третья ступень освоена во всех ----------
const RANKS=['стрелец','стольник','воевода','боярин'],RANK_GOLD=[0,30,60,100],RANK_OK=[0,3,10,25];
const RANK_SAY=['','Быть тебе отныне стольником: / за столом моим — не дворником!','Жалую тебя воеводой: / правь умом, а не погодой!','Будь отныне ты боярин: / шубу дам — ходи как барин!'];
const rankName=()=>S.pz&&S.pz.rank?RANKS[S.pz.rank]:'';
function rankFits(r){const p=S.pz;return p.ok>=RANK_OK[r]&&(r!==2||p.open.length>=PZ.length)&&(r!==3||PZ.every(s=>pzMast(s.id,2)))}
function rankUp(){const up=[];while(S.pz.rank<3&&rankFits(S.pz.rank+1)){const r=++S.pz.rank;S.gold+=RANK_GOLD[r];up.push(r);toast(`Царь жалует тебя: ты ${RANKS[r]}! +${RANK_GOLD[r]} зол.`)}return up}
function rankNext(){const p=S.pz,r=p.rank+1;if(r>3)return'Выше боярина чинов нет.';const n=[],k=RANK_OK[r]-p.ok,c=PZ.length-p.open.length,t=PZ.filter(s=>!pzMast(s.id,2)).length;
  if(k>0)n.push(`ещё ${k} ${pzPl(k,'верное поручение','верных поручения','верных поручений')}`);
  if(r===2&&c>0)n.push(`открыть ещё ${c} ${pzPl(c,'приказ','приказа','приказов')}`);
  if(r===3&&t>0)n.push(`освоить третью ступень ещё в ${t} ${pzPl(t,'приказе','приказах','приказах')}`);
  return`До чина «${RANKS[r]}»: ${n.join(', ')}.`}

// ---------- золото: поручение дня — 10 сразу; малые поручения (5) и задачи приказов (2/3/5) — жалованье ----------
// Жалованье платят только в день, когда стрелец вернулся из похода с добычей, и не больше 15 в день: еда на день стоит ~19,4,
// так что без похода стрелец кормится лишь наполовину. Расчёт — docs/PROJECT.md, раздел 5.
const PZ_DAY_GOLD=10,PZ_SMALL_GOLD=5,PZ_PAY=[2,3,5],PZ_PAY_DAY=15;
const payToday=()=>S.pz.pay.day===today()?S.pz.pay.g:0;
function payOut(g){const p=S.pz.pay,t=today();if(p.day!==t){p.day=t;p.g=0}
  if(S.wonDay!==t)return{g:0,why:'жалованье платят только в день похода с добычей'};
  const x=Math.min(g,PZ_PAY_DAY-p.g);if(x<=0)return{g:0,why:`жалованье на сегодня выдано, ${PZ_PAY_DAY} зол.`};p.g+=x;S.gold+=x;return{g:x}}

// ---------- царь: раёшник ----------
const TSAR_OFFER=['Слушай царский мой указ: / сосчитай-ка мне сейчас!','Эй, стрелец, поди сюда: / у казны опять беда.','Дьяки мои — сплошь ротозеи: / сочти-ка ты, да поскорее!','Есть задачка для ума: / не осилит и кума.','Прежде чем в лесу палить, / помоги казну делить!'];
const TSAR_LATER=['Отложил? Ну что ж, ступай. / Да смотри, не забывай!','Ладно, ладно, не горит… / Хотя казна уже дымит.','Отложил, а я терпи! / Ну, ступай… да не храпи.'];
const TSAR_OK=['Ай да счёт, ай да стрелец! / Вот награда, молодец!','Сошлось! Ну, порадовал царя: / не зря кормлю тебя, не зря!','Вот голова! Не то что дьяк: / тот бы счёл, да всё не так.','Казне прибыток, мне — покой. / Служи и дальше так, родной!'];
const TSAR_BAD=['Что ты мне тут насчитал? / Чтоб тебя Кощей забрал!','Ты считал или гадал? / Я такого не видал!','Ну и счёт — сплошной обман: / в голове-то, брат, туман!','Мимо! Ох, стрелец, беда: / так казна уйдёт в никуда.'];
const TSAR_NO=['Сдался? Ишь, какой ленивый! / Ступай, стрелец неторопливый.','Отказался? Вот те раз! / Плакал, значит, мой указ.','Струсил счёта, как огня? / Ох, расстроил ты меня!'];
const TSAR_HALL=['Заходи, стрелец, в палаты: / тут приказы, тут и платы.','Здесь дьяки скрипят пером: / счёт ведут — и мы живём.','Кто в приказах счёт ведёт, / тот в чинах идёт вперёд.'];
// диалоги над картой: царь (t) напоминает об отложенном поручении или даёт малое
const TSAR_REASK=[[['t','А указ мой где, стрелец? / Позабыл, поди, хитрец!','angry'],['s','Помню, батюшка, помню, царь! / Счёты — вот они, как встарь.']],
  [['t','Я указ тебе давал? / Аль ты, братец, задремал?'],['s','Не дремал я, царь, — считал: / только свиток не достал.']]];
const TSAR_SMALL=[[['t','Подойди-ка, удалец: / есть делишко под конец.'],['s','Малое дело — не беда, / подавай его сюда!']],
  [['t','Дьяк мой путает с утра — / подсоби ему, пора.'],['s','Подсоблю, коль надо, царь: / дай-ка свиток и букварь.']],
  [['t','Скучно мне, стрелец, без цифр: / ну-ка, разгадай мне шифр!'],['s','Разгадаю, царь, изволь: / только жалованье — не ноль!']]];
const DYAK_OK=['Верно, по-приказному.','Сошлось до копейки.','Так и запишем в книгу.'],DYAK_BAD=['Не сходится. Проверь формулу.','Ошибка в счёте. Глянь решение.'];
const pzEnd=t=>/[.!?]$/.test(t)?t:t+'.';   // «300 руб.» без второй точки
const rhyme=t=>`<i>«${t.split(' / ').join('<br>')}»</i>`;

// ---------- поручения: одно в день при входе, отложенное царь напомнит над картой; малых — до двух в день ----------
// Новый приказ царь даёт, когда освоена первая ступень последнего открытого. Иначе — из открытого приказа на верхней открытой ступени, слабые чаще.
function tsarPick(){const p=S.pz,nx=PZ.find(s=>!pzOpen(s.id)),last=p.open[p.open.length-1];
  if(nx&&(!last||pzMast(last,0)))return{sec:nx.id,step:0};
  const w=p.open.map(id=>{const q=p.st[id+pzTopStep(id)];return 1+(1-(q&&q.r.length?pzAcc(q):.7))*4});let x=Math.random()*pzSum(w);
  for(let i=0;i<w.length;i++){x-=w[i];if(x<=0)return{sec:p.open[i],step:pzTopStep(p.open[i])}}
  return{sec:last,step:pzTopStep(last)}}
// st: new → offered (царь сказал) → later (отложено) | taken (задача выдана) → ok | bad | no (отказ); у малого ещё gone — отложено, пропало
function tsarDay(){const p=S.pz,t=today();if(!p.task||p.task.day!==t){p.task={day:t,st:'new',...tsarPick(),p:null};save()}return p.task}
const smallLive=()=>{const m=S.pz.small;return m&&m.day===today()&&(m.st==='offered'||m.st==='taken')?m:null};
function tsarPanel(){if(!S.pz||!S.intro)return'';const T=tsarDay(),m=smallLive(),k=['new','offered','taken'].includes(T.st)?'day':m?'small':'';if(!k)return'';
  const o=k==='day'?T:m,s=PZ_BY[o.sec],nw=!pzOpen(o.sec);
  return`<div class="panel"><div class="row"><span class="px small gold" style="flex:1">${k==='day'?'Поручение дня':'Малое поручение'} от царя</span><span class="small muted">${s.name} · ${s.topic} · ступень ${o.step+1}</span></div>
    <p class="small" style="margin:8px 0">Награда: ${k==='day'?PZ_DAY_GOLD+' зол.':PZ_SMALL_GOLD+' зол. жалованья'}${nw?`, и ${s.name} откроется в палатах`:''}${RANK_OK[S.pz.rank+1]?', шаг к новому чину':''}. Ошибёшься или откажешься — царь осерчает, награды не будет.</p>
    <div class="row"><button class="main" data-act="pztake" data-k="${k}">${o.st==='taken'?'Вернуться к поручению':'Взяться'}</button><button data-act="pzlater" data-k="${k}">Отложить</button></div></div>`}
function tsarPanelUpd(){const el=document.getElementById('tsarTask');if(el)el.innerHTML=tsarPanel()}
// каждый тик faces.js, пока на экране царь над картой: новое поручение дня он объявляет сам
function tsarTick(){if(typeof S==='undefined'||!S.pz||!S.intro)return;const T=tsarDay();if(T.st!=='new')return;T.st='offered';save();
  say('tsar',pzOpen(T.sec)?pick(TSAR_OFFER):PZ_BY[T.sec].tsar);tsarPanelUpd()}
// вызывается из talk() в faces.js: true — царь завёл свой разговор вместо обычного
function tsarTalk(click){if(typeof S==='undefined'||!S.pz||!S.intro||!document.querySelector('.say[data-who="tsar"]'))return false;const T=tsarDay(),g=Math.random();
  const dlg=(d,fn)=>{d.forEach(([w,t,m],i)=>say(w==='t'?'tsar':'strelets',t,m,g,i===d.length-1?fn:null));TK.last=Date.now()};
  if(T.st==='later'&&(click||Math.random()<.5)){dlg(pick(TSAR_REASK),()=>{if(T.st==='later'){T.st='offered';save();tsarPanelUpd()}});return true}
  const m=S.pz.small,n=m&&m.day===today()?m.n:0;
  if(['ok','bad','no'].includes(T.st)&&!smallLive()&&n<2&&Math.random()<(click?.4:.3)){
    dlg(pick(TSAR_SMALL),()=>{S.pz.small={day:today(),n:n+1,st:'offered',...tsarPick(),p:null};save();tsarPanelUpd()});return true}
  return false}

// ---------- экран поручения: царь велит, ответ один ----------
let tz=null;   // {k: 'day' | 'small', res: итог}
const tzObj=k=>k==='day'?S.pz.task:S.pz.small;
const tsarFace=()=>'<canvas class="face" data-face="tsar" width="64" height="64"></canvas>';
const PZ_FH='Ответ — число: 1200, 7,5 или 25%. Единицы писать не обязательно.';
const pzSolHTML=e=>`<div class="sol"><div class="small muted">Решение:</div><ol>${e.s.map(stepLi).join('')}</ol><div class="small">Ответ: ${pzFa(e)}</div></div>`;
const pzFormulas=s=>`<details class="pzf"><summary class="small">Формулы: ${s.name}</summary><ul class="small">${s.rules.map(r=>`<li>${r}</li>`).join('')}</ul></details>`;
const pzMsg=(t,c)=>{const m=$('#pzmsg');if(m)m.innerHTML=`<span class="${c}">${t}</span>`};
function tzTake(k){const o=tzObj(k);if(!o||!['new','offered','later','taken'].includes(o.st))return;if(!o.p)o.p=pzGen(o.sec,o.step);o.st='taken';save();tz={k,res:null};
  if(!S.pz.tut[o.sec])startDyak(o.sec,()=>show(tzView));else show(tzView)}
function tzLater(k){const o=tzObj(k);if(!o)return;o.st=k==='day'?'later':'gone';save();if(k==='day')say('tsar',pick(TSAR_LATER));tsarPanelUpd()}
function tzView(){const o=tz&&tzObj(tz.k);if(!o||!o.p)return show(mapScreen);const s=PZ_BY[o.sec],e=o.p,r=tz.res;let b;
  if(!r)b=`<p class="muted small">Царь велит:</p><p class="pzq">${e.q}</p>
    <div class="row" style="flex-wrap:nowrap"><input id="pzans" autocomplete="off" spellcheck="false" placeholder="ответ"><button class="main" data-act="pzans">Ответить</button></div>
    <div class="small muted" style="margin-top:6px">${PZ_FH}</div><div class="msg" id="pzmsg"></div>`;
  else b=`<p>${rhyme(r.say)}</p><p class="small muted">${e.q}</p>
    <p class="${r.ok?'ok':'bad'}">${r.ok?'Верно: '+pzFa(e):(r.no?'Отказ.':`Неверно: у тебя ${r.v}.`)+` Верный ответ: ${pzEnd(pzFa(e))}`}</p>${r.gift?`<p class="gold">${r.gift}</p>`:''}
    <div id="pzsol"><button data-act="pzsol">Показать решение</button></div>`;
  app.innerHTML=`<div class="panel tut pz"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div>${tsarFace()}<div class="px small c gold">Царь</div></div><div class="bubble">${b}</div></div>
    <div class="row" style="margin-top:12px"><span class="small muted" style="flex:1;min-width:200px">${tz.k==='day'?'Поручение дня':'Малое поручение'} · ${s.name} · ступень ${o.step+1}, ${PZ_STEP[o.step]}</span>
    ${r?'<button data-act="pzpal">В палаты</button><button class="main" data-act="map">На карту</button>':`<button data-act="pzno">Отказаться</button><button data-act="pzlater" data-k="${tz.k}">Отложить</button>`}</div>
    ${pzFormulas(s)}</div>`;
  const a=$('#pzans');if(a){a.focus();a.onkeydown=ev=>{if(ev.key==='Enter')tzAnswer()}}}
function tzAnswer(no){const o=tzObj(tz.k),e=o.p;let ok=false,v='';
  if(no){if(!confirm('Отказаться от поручения? Царь осерчает, награды не будет.'))return}
  else{v=$('#pzans').value;if(!v.trim())return pzMsg('Сначала впиши ответ','muted');const c=pzCheck(e,v);if(c.err)return pzMsg(c.err,'muted');ok=c.ok;pzRec(o.sec,o.step,ok)}
  const gift=[];let line;
  if(ok){o.st='ok';S.pz.ok++;
    if(tz.k==='day'){S.gold+=PZ_DAY_GOLD;gift.push(`+${PZ_DAY_GOLD} зол.`)}else{const x=payOut(PZ_SMALL_GOLD);gift.push(x.g?`+${x.g} зол. жалованья`:`Золота нет: ${x.why}`)}
    if(!pzOpen(o.sec)){S.pz.open.push(o.sec);gift.push(`${PZ_BY[o.sec].name} открыт в палатах`)}
    const up=rankUp();up.forEach(r=>gift.push(`чин «${RANKS[r]}», +${RANK_GOLD[r]} зол.`));line=up.length?RANK_SAY[up[up.length-1]]:pick(TSAR_OK)}
  else{o.st=no?'no':'bad';line=pick(no?TSAR_NO:TSAR_BAD)}
  save();tz.res={ok,no,v:v.trim(),say:line,gift:gift.join(' · ')};FS.tsar.st=ok?'pleased':'angry';setTimeout(()=>{if(!SPK.cur)FS.tsar.st='neutral'},6000);show(tzView)}

// ---------- палаты: открытые приказы, ступени, жалованье ----------
function pzBar(sec,k){const q=S.pz.st[sec+k],ok=q?q.ok:0,a=q&&q.r.length?pzAcc(q):0,m=pzMast(sec,k);
  return`<div class="pzbar"><div class="bar m"><i style="width:${Math.min(1,ok/8)*Math.min(1,a/.7)*100}%"></i></div><span class="small ${m?'gold':'muted'}">${m?'освоено · ':''}${Math.min(ok,8)}/8 · ${q&&q.r.length?Math.round(a*100)+'%':'—'}</span></div>`}
function palatyHTML(){const p=S.pz,T=tsarDay(),m=smallLive();
  const st={new:'ждёт тебя',offered:'ждёт тебя',later:'отложено',taken:'начато',ok:'выполнено',bad:'не вышло',no:'ты отказался'}[T.st];
  const act=['new','offered','later','taken'].includes(T.st)?` <button class="main" data-act="pztake" data-k="day">${T.st==='taken'?'Вернуться к поручению':'Взяться'}</button>`:'';
  const top=`<div class="panel tut pz"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div>${tsarFace()}<div class="px small c gold">Царь</div></div><div class="bubble">
    <p>${rhyme(pick(TSAR_HALL))}</p><p>Чин: <b>${RANKS[p.rank]}</b> · верных поручений: ${p.ok}.<br><span class="small muted">${rankNext()}</span></p>
    <p>Поручение дня — ${PZ_BY[T.sec].name}, ступень ${T.step+1}: <b>${st}</b>.${act}</p>${m?`<p>Малое поручение — ${PZ_BY[m.sec].name}. <button data-act="pztake" data-k="small">Взяться</button></p>`:''}</div></div></div>`;
  const list=PZ.map(s=>pzOpen(s.id)?`<div class="pzsec"><div class="row"><span class="px small gold" style="flex:1">${s.name}</span><button data-act="pzdyak" data-s="${s.id}">Урок дьяка</button></div>
      <div class="small muted" style="margin:4px 0 6px">${pzCap(s.topic)}: ${s.what}.</div>
      ${[0,1,2].map(k=>`<div class="pzstep"><span class="small pzname">${k+1}. ${pzCap(PZ_STEP[k])}</span>${pzUnl(s.id,k)?pzBar(s.id,k)+`<button data-act="pzgo" data-s="${s.id}" data-n="${k}">Решать</button>`:`<span class="small muted">откроется, когда освоишь ступень ${k}</span>`}</div>`).join('')}</div>`
    :`<div class="pzsec off"><div class="px small muted">${s.name}</div><div class="small muted">${pzCap(s.topic)}: ${s.what}. Откроется, когда выполнишь поручение царя из этого приказа.</div></div>`).join('');
  return top+`<div class="panel"><h2>Приказы</h2>${p.open.length?'':'<p class="muted">Ни один приказ ещё не открыт. Выполни поручение царя — откроется первый.</p>'}${list}
    <p class="small muted" style="margin-top:12px">Поручение дня — ${PZ_DAY_GOLD} зол. Малые поручения (царь даёт их в разговоре над картой) — ${PZ_SMALL_GOLD} зол., задачи приказов — ${PZ_PAY.join(' / ')} зол. по ступеням. Это жалованье: его платят только в день, когда стрелец вернулся из похода с добычей, и не больше ${PZ_PAY_DAY} зол. в день. ${S.wonDay===today()?`Сегодня выдано ${payToday()} из ${PZ_PAY_DAY}.`:'Сегодня похода с добычей ещё не было.'} Норму дня закрывает только поход.</p></div>`}

// ---------- решать ступень в палатах ----------
let pzPr=null;   // {sec, k, e: задача, res}
function pzGo(sec,k){pzPr={sec,k,e:pzGen(sec,k),res:null};show(pzView)}
function pzView(){const{sec,k,e,res}=pzPr,s=PZ_BY[sec];view=pzView;
  app.innerHTML=`${hdr()}<div class="panel"><div class="row"><h1 style="flex:1;margin:0">${s.name}</h1><button data-act="pzpal">← В палаты</button></div>
    <p class="small muted" style="margin:8px 0 6px">${pzCap(s.topic)} · ступень ${k+1}, ${PZ_STEP[k]}. ${PZ_HOW[k]}</p>${pzBar(sec,k)}</div>
    <div class="panel"><p class="pzq">${e.q}</p>
    ${res?`<div class="msg"><span class="${res.ok?'ok':'bad'}">${res.txt}</span></div><div class="row" style="margin-top:8px"><button class="main" data-act="pznext" id="pznext">Следующая задача</button><button data-act="pzsol">Решение</button></div><div id="pzsol"></div>`
      :`<div class="row" style="flex-wrap:nowrap"><input id="pzans" autocomplete="off" spellcheck="false" placeholder="ответ"><button class="main" data-act="pzcheck">Проверить</button></div><div class="small muted" style="margin-top:6px">${PZ_FH}</div><div class="msg" id="pzmsg"></div>`}
    ${pzFormulas(s)}</div>`;
  paintAll();const a=$('#pzans');if(a){a.focus();a.onkeydown=ev=>{if(ev.key==='Enter')pzAnswer()}}else{const n=$('#pznext');if(n)n.focus()}}
function pzAnswer(){const P=pzPr;if(!P||P.res)return;const v=$('#pzans').value;if(!v.trim())return pzMsg('Сначала впиши ответ','muted');const c=pzCheck(P.e,v);if(c.err)return pzMsg(c.err,'muted');
  pzRec(P.sec,P.k,c.ok);let txt;
  if(c.ok){const x=payOut(PZ_PAY[P.k]);txt=`Верно: ${pzEnd(pzFa(P.e))} ${x.g?`+${x.g} зол. жалованья.`:`Золота нет: ${x.why}.`}`;rankUp()}
  else txt=`Неверно: у тебя ${v.trim()}, а верно ${pzEnd(pzFa(P.e))}`;
  save();P.res={ok:c.ok,txt};pzView()}

// ---------- урок дьяка перед новым приказом: формулы, пример по шагам, 3 тренировки ----------
let dk=null;   // {sec, stage: rules | ex | prac, step, done, e, after, lib}
const DYAK_ICON='<svg class="dyak" viewBox="0 0 16 16" width="128" height="128" shape-rendering="crispEdges"><rect x="4" y="2" width="8" height="12" fill="#d8c8a0"/><rect x="3" y="1" width="10" height="2" fill="#8a6a3a"/><rect x="3" y="13" width="10" height="2" fill="#8a6a3a"/>'+
  '<rect x="5" y="4" width="6" height="1" fill="#5a4128"/><rect x="5" y="6" width="6" height="1" fill="#5a4128"/><rect x="5" y="8" width="4" height="1" fill="#5a4128"/><rect x="8" y="10" width="3" height="3" fill="#9a2a2a"/><rect x="13" y="3" width="1" height="7" fill="#e8dcc4"/><rect x="12" y="10" width="1" height="2" fill="#2a1c10"/></svg>';
function startDyak(sec,after,lib){dk={sec,stage:'rules',step:0,done:0,e:null,after,lib};show(dkView)}
function dkView(){const s=PZ_BY[dk.sec];let b;
  if(dk.stage==='rules')b=`<h2>${s.name}</h2><p>${rhyme(s.dyak)}</p><p class="small">${pzCap(s.topic)}: ${s.what}.</p><ul>${s.rules.map(r=>`<li>${r}</li>`).join('')}</ul>
    <p class="small muted">В приказе три ступени: прямой расчёт по формуле, обратная задача (неизвестное внутри формулы — решаем уравнением) и многошаговая. Следующая ступень открывается, когда на этой 8 верных и 70% из последних 10.</p>
    <div class="row"><button class="main" data-act="dknext">Покажи пример</button></div>`;
  else if(dk.stage==='ex')b=`<p class="muted small">Пример</p><p class="pzq">${s.ex.q}</p><ol class="steps">${s.ex.s.slice(0,dk.step).map(stepLi).join('')}</ol>
    <div class="row">${dk.step<s.ex.s.length?'<button class="main" data-act="dkstep">Следующий шаг</button>':'<button class="main" data-act="dknext">Теперь сам</button>'}</div>`;
  else b=`<p class="muted small">Тренировка ${dk.done+1} из 3 · без награды</p><p class="pzq">${dk.e.q}</p>
    <div class="row" style="flex-wrap:nowrap"><input id="pzans" autocomplete="off" spellcheck="false" placeholder="ответ"><button class="main" data-act="dkcheck">Проверить</button></div>
    <div class="small muted" style="margin-top:6px">${PZ_FH}</div><div class="msg" id="pzmsg"></div><div id="pzsol"></div>`;
  app.innerHTML=`<div class="panel tut pz"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div>${DYAK_ICON}<div class="px small c gold">Дьяк</div></div><div class="bubble">${b}</div></div>
    <div class="row" style="margin-top:12px"><span class="small muted">Урок дьяка · ${s.name}</span><span style="flex:1"></span><button data-act="dkskip">${dk.lib?'Закрыть урок':'Знаю, пропустить'}</button></div></div>`;
  const a=$('#pzans');if(a){a.focus();a.onkeydown=ev=>{if(ev.key==='Enter')dkCheck()}}}
function dkCheck(){const a=$('#pzans');if(!a.value.trim())return pzMsg('Сначала впиши ответ','muted');const c=pzCheck(dk.e,a.value);if(c.err)return pzMsg(c.err,'muted');
  if(c.ok){dk.done++;if(dk.done>=3)return dkDone();dk.e=pzGen(dk.sec,0);dkView();pzMsg(pick(DYAK_OK),'ok')}
  else pzMsg(`${pick(DYAK_BAD)} <button data-act="dksol">Показать решение</button>`,'bad')}
function dkDone(){S.pz.tut[dk.sec]=1;save();const f=dk.after;dk=null;f()}

document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const d=b.dataset;
  const A={pztake:()=>tzTake(d.k),pzlater:()=>{const back=view===tzView;tzLater(d.k);if(back)show(mapScreen)},pzans:()=>tzAnswer(),pzno:()=>tzAnswer(true),
    pzsol:()=>{const e=view===tzView?tz&&tzObj(tz.k).p:pzPr&&pzPr.e;if(e)$('#pzsol').innerHTML=pzSolHTML(e)},
    pzpal:()=>show(()=>building('palaty')),pzgo:()=>pzGo(d.s,+d.n),pzcheck:pzAnswer,pznext:()=>{pzPr.e=pzGen(pzPr.sec,pzPr.k);pzPr.res=null;pzView()},
    pzdyak:()=>{const back=view;startDyak(d.s,()=>show(back),true)},
    dknext:()=>{if(dk.stage==='rules'){dk.stage='ex';dk.step=0}else{dk.stage='prac';dk.e=pzGen(dk.sec,0)}dkView()},dkstep:()=>{dk.step++;dkView()},
    dkcheck:dkCheck,dkskip:dkDone,dksol:()=>{$('#pzsol').innerHTML=pzSolHTML(dk.e)+'<div class="row" style="margin-top:8px"><button data-act="dknew">Другая задача</button></div>'},
    dknew:()=>{dk.e=pzGen(dk.sec,0);dkView()}};
  A[d.act]&&A[d.act]()});
